"""Audit and report compact pure-FusDense training; no deployment side effects."""
import json,hashlib,shutil,datetime
from pathlib import Path
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
ROOT=Path(__file__).resolve().parents[1];RUN=ROOT/'reports/pure_capacity_20261108'
def read(p):return json.loads(p.read_text(encoding='utf-8'))
def row(name,n,r,ok):
 c=r['classification_report'];d=c['disgust'];return f"| {name} | {n} | {r['accuracy']:.2%} | {c['macro avg']['f1-score']:.4f} | {d['precision']:.4f}/{d['recall']:.2%}/{d['f1-score']:.4f} | {c['happy']['recall']:.2%} | {c['surprise']['recall']:.2%} | {c['neutral']['recall']:.2%} | {ok} |"
def main():
 decision=read(RUN/'deployment_decision.json');head=read(RUN/'head_history.json');full=read(RUN/'full_history.json');protocol=read(RUN/'protocol.json');current=read(RUN/'current_validation.json');norm=read(RUN/'normalization_audit.json');protected={name:hashlib.sha256((ROOT/name).read_bytes()).hexdigest()==sha for name,sha in read(RUN/'protected_artifacts.json').items()}
 lines=['# Pure FusDenseNet capacity-control results','', 'Experiment started8November2026; report generated '+datetime.datetime.now().astimezone().isoformat()+'. These are actual measured outcomes, not original-paper results.','',f"Eligible for deployment: **{decision['eligible']}**. New full-test candidate evaluated: **{decision['test_evaluated']}**. All protected model/app/PPT hashes unchanged before any integration: **{all(protected.values())}**.",'',decision['reason'],'','## Architecture and training changes','', 'The deployed 1,828,896-parameter model has 1,681,415 classifier parameters (91.94%). Its original TRAIN accuracy is92.08%, versus58.41% validation accuracy; TRAIN disgust recall100% versus36% validation. This proves a large generalization gap, not a specific single cause. Previous reweighting/mixup trials did not yield a qualifying replacement.','', 'This experiment keeps the native stem, three fusion-dense stages, cross-dense concatenations, dilated convolutions, cross-attention and final mean/max/RMS/2x2 pooling. A fixed differentiable spatial transform coarsens the two fine4x4 shortcut grids into2x2 mean/max regions and normalizes each concatenated shortcut. Feature width3276 becomes1260. Smaller randomly initialized128/256 classifiers have309,792/472,096 total parameters, respectively, reducing total capacity83.06%/74.19%. These are explicit project choices, not recovered author settings.','', 'Four independent native heads use normalized original/mirrored TRAIN features,10% feature dropout,50% hidden dropout,label smoothing.025,AdamW decay.1 and varying common-class loss costs. The TRAIN-only standard-deviation floor is.05; '+str(norm['features_below_std_floor'])+' of1260features fall below it. A smaller train/validation gap with lower validation accuracy is underfitting, not an improvement.','', 'The next phase fine-tunes the full native feature path with mild TRAIN-only affine/brightness/contrast augmentation and complementary mirror views. BatchNorm running statistics stay frozen. The training reference is the original pure classifier on correctly labelled TRAIN disgust-vs-rest positive/negative examples, discarded at inference. No external encoder, hybrid inference, probability ensemble, class offset or held-out target in training is used.','', 'The pooling/capacity/optimizer/augmentation changes form one exploratory engineering intervention, not an isolated equal-compute causal ablation. New heads are independently initialized; rejected recipes are not ancestors of selected weights. Head and full-network epochs have different cost.','',f"Completed: {len(head)} classifier epochs across four recipes, plus {len(full)} full-network epochs. All23,503natural training sources are seen in each full epoch. Two orientations are views of existing TRAIN images, not new subjects.",'','## Actual full-validation results','', 'All3,970retained validation faces and all50disgust examples are included. Per-recipe rows are the highest feasibility checkpoint, not cherry-picked test results. Feasibility penalizes unmet gates and is not an accuracy/F1 metric.','', '| Stage | Epochs | Accuracy | Macro F1 | Disgust P/R/F1 | Happy recall | Surprise recall | Neutral recall | Meets all gates |','|---|---:|---:|---:|---|---:|---:|---:|---|',row('Deployed pure baseline','-',current,'baseline')]
 for recipe in protocol['recipes']:
  group=[r for r in head if r['recipe']==recipe['name']];best=max(group,key=lambda r:r['feasibility_objective']);r=read(RUN/recipe['name']/f"validation_{best['recipe_epoch']:03d}_{best['kind']}.json");lines.append(row(recipe['name'],len(group),r,best['eligible']))
 for i,r in enumerate(full,1):lines.append(row(f"Full epoch{i} ({r['kind']})",1,read(RUN/f"full_validation_{i:02d}_{r['kind']}.json"),r['eligible']))
 if 'timing_amendment' in protocol:
  lines+=['','Timing limitation: long wall-clock intervals of716s and1655s occurred during otherwise4-6s head epochs; the pause cause is unconfirmed. The128/common1.2 recipe therefore stopped after one completed epoch and is undertrained, not a comparable converged fit. Its output is preserved and not hidden. Before full-network training/test access, the timing-only amendment switched the full budget to process CPU seconds divided by4threads and enforced at least3completed epochs. The6epoch maximum, training losses and all validation/test gates stayed unchanged. Both source versions and the declaration are retained in timing_amendment/.']
 lines+=['','## Frozen-candidate policy and actual test outcome','',protocol['test_gate'],'', 'No alternate candidate is tested after a test failure. Every test class, face and error remains included. Positive validation temperature calibration changes confidence, not argmax decisions.']
 if decision['test_evaluated']:
  report=read(RUN/'deployment/reports/emotion_evaluation.json');lines+=['',row('Frozen single-model TEST','-',report,decision['eligible']),'','The test row uses6,561faces; validation rows above use3,970. Full7class reports, confusion matrix and prediction arrays are retained in deployment/reports/emotion_evaluation.json.']
 else:lines+=['', 'No validation checkpoint qualified, so no new test accuracy or recall is claimed. The existing deployed full-test result remains58.34% accuracy,0.5554macroF1,46.84%disgust recall (37/79). The app and PPT remain unchanged.']
 lines+=['','## Verification and limits','', 'Four new contract tests passed (18.68seconds): native-vs-cached feature equivalence, retained attention gradients, checkpoint roundtrip and detached training references. The raw-image preflight used64validation images; maximum feature discrepancy2.384e-6. It read no test images. No user photograph or sensor data was used.','', 'Validation has been repeatedly reused and the historical test previously inspected. This is not fresh subject-disjoint, webcam-domain or clinical confirmation. EEG/HRV and weather efficacy results are unchanged. Failure to meet the gate is reported; no80% result or improvement from parameter reduction alone is claimed.','', 'Protocols, executed source hashes, normalization audit, preflight, every student/EMA validation report, histories and deployment decision remain in reports/pure_capacity_20261108/. Experimental architecture code is isolated in scripts/compact_fusdense.py; the live backend is modified only after a successful full-test gate.','', 'Rebuild this report after completion:','', '```powershell',r'.\.venv\Scripts\python.exe -m scripts.report_compact_capacity','```']
 audit=read(RUN/'active_model_feature_group_sensitivity.json');lines+=['','## Existing-model feature-group sensitivity','', 'A fixed deployed model was evaluated on all3970validation faces after replacing one group by its TRAIN mean. This is an input sensitivity check, not a retrained/causal ablation or a test result. No test data was read.','', '| Replaced group | Validation accuracy | Macro F1 | Disgust recall |','|---|---:|---:|---:|']
 for name,r in audit['reports'].items():lines.append(f"| {name} | {r['accuracy']:.2%} | {r['classification_report']['macro avg']['f1-score']:.4f} | {r['classification_report']['disgust']['recall']:.2%} |")
 (ROOT/'PURE_CAPACITY_RESULTS.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
 keys=['val_accuracy','val_macro_f1','val_disgust_recall','val_happy_recall','val_surprise_recall','val_neutral_recall'];b=current['classification_report'];base=[current['accuracy'],b['macro avg']['f1-score'],b['disgust']['recall'],b['happy']['recall'],b['surprise']['recall'],b['neutral']['recall']]
 for phase,records in [('head',head),('full',full)]:
  fig,axes=plt.subplots(2,3,figsize=(16,8))
  for ax,key,bv in zip(axes.flat,keys,base):
   if phase=='head':
    for recipe in protocol['recipes']:
     group=[r for r in records if r['recipe']==recipe['name']];ax.plot(range(1,len(group)+1),[r[key] for r in group],label=recipe['name'],marker='o' if len(group)==1 else None)
   else:ax.plot(range(1,len(records)+1),[r[key] for r in records],marker='o',label='Full-network fine-tuning')
   ax.axhline(bv,color='black',linestyle='--',label='Deployed validation baseline');ax.set(title=key.replace('_',' '),xlabel='Epoch within '+phase+' phase');ax.grid(alpha=.2)
  axes[0,0].legend(fontsize=7);fig.suptitle('Actual compact pure-FusDenseNet validation results: '+phase+' phase');fig.tight_layout();fig.savefig(RUN/(phase+'_validation_curves.png'),dpi=140);plt.close(fig)
 (RUN/'final_protected_audit.json').write_text(json.dumps(protected,indent=2),encoding='utf-8');(RUN/'completion.json').write_text(json.dumps({'reported':True,'decision':decision,'protected_unchanged':all(protected.values())},indent=2),encoding='utf-8');print(json.dumps({'report':'PURE_CAPACITY_RESULTS.md','decision':decision,'protected_unchanged':all(protected.values())},indent=2))
if __name__=='__main__':main()
